SELECT tp_table_11.column_0,tp_table_11.column_1, tp_table_12.column_0,tp_table_12.column_1,tp_table_12.column_2 FROM (SELECT top_level_tp_table_2.column_0::bigint,top_level_tp_table_2.column_1::bigint FROM traceprov_read_worker_layer(1::bigint, 4::bigint) AS top_level_tp_table_2) as tp_table_11(column_0,column_1) JOIN (SELECT log_read_to_append_tp_table_3.column_0::bigint,log_read_to_append_tp_table_3.column_1::bigint,log_read_to_append_tp_table_3.column_2::bigint FROM traceprov_read_worker_layer(1::bigint, 3::bigint) AS log_read_to_append_tp_table_3) as tp_table_12(column_0,column_1,column_2) ON (tp_table_11.column_0=tp_table_12.column_0 AND tp_table_11.column_1=tp_table_12.column_1) 